function hologramProcess(data,w,h,opts){
  opts=opts||{};
  var ab=opts.ab!=null?opts.ab:3;
  var slit=opts.slit!=null?opts.slit:3;
  if(ab<0)ab=0; else if(ab>8)ab=8;
  if(slit<2)slit=2; else if(slit>8)slit=8;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++){
    var slitMul=(y%slit===slit-1)?0.55:1;
    for(var x=0;x<w;x++){
      var p=(y*w+x)*4;
      var xr=Math.max(0,Math.min(w-1,x-ab)), xb=Math.max(0,Math.min(w-1,x+ab));
      var r=data[(y*w+xr)*4], g=data[p+1], b=data[(y*w+xb)*4+2];
      // cyan/magenta hologram tint
      out[p]=r*0.85*slitMul; out[p+1]=g*1.05*slitMul; out[p+2]=b*1.2*slitMul; out[p+3]=data[p+3];
    }
  }
  return out;
}

var EXPORTS={hologramProcess:hologramProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HologramForgePure = EXPORTS; }
